---proto_to_ruby---
#include "proto_to_ruby.h"

using namespace ruby_fuzzer;

std::string protoConverter::removeSpecial(const std::string &x)
{
        std::string tmp(x);
        if (!tmp.empty())
                tmp.erase(std::remove_if(tmp.begin(), tmp.end(),
                                         [](char c) { return !(std::isalpha(c) || std::isdigit(c)); } ), tmp.end());
        return tmp;
}

void protoConverter::visit(ArrType const& x)
{
        if (x.elements_size() > 0) {
                int i = x.elements_size();
                m_output << "[";
                for (auto &e : x.elements()) {
                        i--;
                        if (i == 0) {
                                visit(e);
                        } else {
                                visit(e);
                                m_output << ", ";
                        }
                }
                m_output << "]";
        } else {
                m_output << "[1]";
        }
}

void protoConverter::visit(Array const& x)
{
        switch (x.arr_func()) {
                case Array::FLATTEN:
                        visit(x.arr_arg());
                        m_output << ".flatten";
                        break;
                case Array::COMPACT:
                        visit(x.arr_arg());
                        m_output << ".compact";
                        break;
                case Array::FETCH:
                        visit(x.arr_arg());
                        m_output << ".fetch";
                        break;
                case Array::FILL:
                        visit(x.arr_arg());
                        m_output << ".fill";
                        break;
                case Array::ROTATE:
                        visit(x.arr_arg());
                        m_output << ".rotate";
                        break;
                case Array::ROTATE_E:
                        visit(x.arr_arg());
                        m_output << ".rotate!";
                        break;
                case Array::DELETEIF:
                        visit(x.arr_arg());
                        m_output << ".delete_if";
                        break;
                case Array::INSERT:
                        visit(x.arr_arg());
                        m_output << ".insert";
                        break;
                case Array::BSEARCH:
                        visit(x.arr_arg());
                        m_output << ".bsearch";
                        break;
                case Array::KEEPIF:
                        visit(x.arr_arg());
                        m_output << ".keep_if";
                        break;
                case Array::SELECT:
                        visit(x.arr_arg());
                        m_output << ".select";
                        break;
